BEGIN;
CREATE TABLE crm_message_provider_connections(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE RESTRICT,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,provider_key TEXT NOT NULL,channel TEXT NOT NULL CHECK(channel IN ('EMAIL','SMS','WHATSAPP')),enabled BOOLEAN NOT NULL DEFAULT TRUE,public_config JSONB NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(public_config)='object'),version INTEGER NOT NULL DEFAULT 1 CHECK(version>=1),created_by_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,updated_by_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,company_id,branch_id,provider_key,channel));
CREATE INDEX crm_message_provider_connections_scope_idx ON crm_message_provider_connections(tenant_id,company_id,branch_id,enabled);
CREATE TABLE crm_message_provider_secrets(connection_id UUID PRIMARY KEY REFERENCES crm_message_provider_connections(id) ON DELETE CASCADE,encrypted_payload TEXT NOT NULL,key_version TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
COMMIT;
